import{_ as a,C as o,o as c,c as l,a3 as t,E as r}from"./chunks/framework.BZCmpA0A.js";const f=JSON.parse('{"title":"10 · Shell 與 fan 編輯器","description":"","frontmatter":{},"headers":[],"relativePath":"topics/applications.md","filePath":"topics/applications.md","lastUpdated":1793166439000}'),s={name:"topics/applications.md"};function n(h,e,i,p,b,m){const d=o("MermaidDiagram");return c(),l("div",null,[e[0]||(e[0]=t('<h1 id="_10-·-shell-與-fan-編輯器" tabindex="-1">10 · Shell 與 fan 編輯器 <a class="header-anchor" href="#_10-·-shell-與-fan-編輯器" aria-label="Permalink to &quot;10 · Shell 與 fan 編輯器&quot;">​</a></h1><p><code>ls</code> 不帶參數時列出目前目錄；<code>rm /absolute/file</code> 刪除檔案，<code>cp /absolute/source /absolute/destination</code> 複製檔案。<code>cls</code> 會要求終端清除畫面和捲動歷史，保留 WUFS 檔案；捲動歷史是否真的清除取決於終端對控制序列的支援。命令範圍與限制見 <a href="./../SPEC-18-file-commands.html">Spec 18</a>。</p><p>核心提供能力，使用者程式把能力組合成操作。WUWAOS 的 shell 與 fan 都是 U-mode（使用者模式）程式，透過 syscall 操作行程、終端與檔案。</p><h2 id="shell-如何執行命令" tabindex="-1">Shell 如何執行命令 <a class="header-anchor" href="#shell-如何執行命令" aria-label="Permalink to &quot;Shell 如何執行命令&quot;">​</a></h2><p><code>user/shell.c</code> 讀入最多 126 個字元，切成最多 4 個 token（以空白分隔的單位），再比對命令。解析為 O(L)，L 是輸入長度；目前沒有引號、腳本與一般背景工作控制。</p><p>在提示字元輸入 <code>help</code>，每行會列出一個命令及其參數，右側對齊用途說明；行程、檔案與記憶體操作用空白行分隔。<code>&lt;path&gt;</code> 可是相對或絕對路徑，<code>&lt;page&gt;</code> 從 0 起算。格式與驗收見 <a href="./../SPEC-14-shell-help.html">Spec 14</a>。</p><table tabindex="0"><thead><tr><th>操作</th><th>主要流程</th></tr></thead><tbody><tr><td>ps／pcb</td><td>進核心查詢行程狀態</td></tr><tr><td>ls／cat／write／rm／cp</td><td>以路徑呼叫 WUFS 服務</td></tr><tr><td>cls</td><td>透過終端控制序列清除畫面及捲動歷史</td></tr><tr><td>run counter</td><td>fork 子行程，再 exec 指定內建程式 ID</td></tr><tr><td>writer | reader</td><td>建立固定管道與兩個端點行程</td></tr><tr><td>fan 路徑</td><td>fork → exec fan 並傳入路徑 → 父 shell 等待</td></tr><tr><td>vmstat／mem</td><td>查詢與操作使用者記憶體</td></tr></tbody></table><p>命令和 syscall 沒有一對一關係。以 fan 為例，一次編輯操作可能多次讀取按鍵、輸出控制碼，最後才寫入檔案。</p><h2 id="命令是如何被「吃進去」的" tabindex="-1">命令是如何被「吃進去」的？ <a class="header-anchor" href="#命令是如何被「吃進去」的" aria-label="Permalink to &quot;命令是如何被「吃進去」的？&quot;">​</a></h2><p>以在 <code>/home/user</code> 輸入 <code>cat note.txt</code> 為例：</p>',10)),r(d,{source:`flowchart TD
  A[鍵盤輸入 cat note.txt 後按 Enter] --> B[QEMU UART 序列埠收到字元]
  B --> C[核心 I/O 收集一行並交給 shell 的 read]
  C --> D[shell tokenize 切出 cat 與 note.txt]
  D --> E[command 依名稱和參數數量選擇 cat]
  E --> F[使用者 API 執行 ecall 系統呼叫指令]
  F --> G[trap 例外入口保存狀態並進入核心]
  G --> H[syscall_dispatch 依系統呼叫編號分派]
  H --> I[核心結合 PCB 的目前目錄查詢 WUFS]
  I --> J[讀取內容回傳 shell，經 write 輸出]
`}),e[1]||(e[1]=t('<ol><li>UART（序列埠）接收終端字元；核心 I/O 完成一行後，shell 的 <code>read</code> 拿到文字。</li><li>shell 的 <code>tokenize</code>（切詞）依空白分出命令與參數；<code>command</code> 比對第一個詞和參數數量。<code>cat</code>、<code>cd</code>、<code>ls</code> 是 shell 認得的內建命令，不是 Linux 程式，也不代表每個命令都是 syscall。</li><li><code>cat</code> 呼叫使用者 API 的檔案讀取介面。API 將 syscall 編號放入 <code>a7</code>（系統呼叫編號暫存器），參數放入 <code>a0</code> 等暫存器，執行 <code>ecall</code>（進入核心的指令）。</li><li>硬體依 <code>stvec</code>（監督模式例外入口位址暫存器）轉到例外入口；核心保存行程狀態後，<code>syscall_dispatch</code>（系統呼叫分派器）依編號選擇檔案讀取。核心使用該行程 PCB 的 CWD（目前工作目錄），將 <code>note.txt</code> 視為 <code>/home/user/note.txt</code>，再逐層查找 WUFS。</li><li>核心將資料和結果交回 shell，shell 透過輸出 syscall 印出；<code>sepc</code>（例外返回指令位址暫存器）跳過剛執行的 <code>ecall</code>，最後 <code>sret</code>（返回使用者模式指令）恢復執行。若找不到檔案則顯示錯誤。</li></ol><p><code>cd</code> 呼叫 chdir 改變本行程 PCB 的目錄，<code>pwd</code> 呼叫 getcwd 取得目錄；<code>cls</code> 輸出終端控制序列，<code>fan</code> 則 fork 子行程再 exec 對應內建映像。一個命令可以呼叫多次 syscall；目前沒有 PATH 搜尋或一般外部 ELF 程式載入。</p><h2 id="目錄操作" tabindex="-1">目錄操作 <a class="header-anchor" href="#目錄操作" aria-label="Permalink to &quot;目錄操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>功能</th></tr></thead><tbody><tr><td><code>pwd</code></td><td>顯示目前目錄</td></tr><tr><td><code>cd</code>、<code>cd ~</code></td><td>切到 <code>/home/user</code></td></tr><tr><td><code>cd notes</code>、<code>cd ~/notes</code></td><td>以相對路徑或家目錄路徑進入</td></tr><tr><td><code>cd ..</code>、<code>cd /</code></td><td>前往上一層或根目錄</td></tr><tr><td><code>cd -</code></td><td>返回前一個目錄並印出路徑</td></tr><tr><td><code>ls</code></td><td>列出目前目錄</td></tr></tbody></table><p>提示字元顯示完整目前路徑，例如 <code>wuwaos/&gt;</code>、<code>wuwaos/note&gt;</code>；若取得目錄失敗則顯示 <code>wuwaos?&gt;</code>。初始 shell 從 <code>/</code> 開始。spawn、fork 或 pipe 新建的子行程繼承目錄，exec 保留；之後各行程各自管理。目標不存在或不是目錄時不會改變位置。規格與驗收見 <a href="./../SPEC-19-cwd-shell.html">Spec 19</a>。<a href="https://github.com/johnson931128/WUWAOS/blob/main/user/shell.c" target="_blank" rel="noreferrer">shell 原始碼</a>、<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/syscall.c" target="_blank" rel="noreferrer">系統呼叫分派</a>。</p><h2 id="三份獨立使用者映像" tabindex="-1">三份獨立使用者映像 <a class="header-anchor" href="#三份獨立使用者映像" aria-label="Permalink to &quot;三份獨立使用者映像&quot;">​</a></h2><p>Makefile 將 shell、app、fan 分別連結為 ELF，再轉成 binary 嵌入核心。<code>kernel/user_image.S</code> 保存原始內容，VM 在需要時載入對應頁面。</p><p>因此 fan 是真正的獨立行程，但還不是由 <code>/bin/fan</code> 磁碟執行檔載入。user/entry.S 將初始參數交給 user_main，返回值再交給 exit。</p><h2 id="fan-的文字資料結構" tabindex="-1">fan 的文字資料結構 <a class="header-anchor" href="#fan-的文字資料結構" aria-label="Permalink to &quot;fan 的文字資料結構&quot;">​</a></h2><p><code>user/fan.c</code> 用連續 byte 陣列存放最多 2048 bytes ASCII／LF 文字，cursor（游標）是陣列中的位移。</p><p>例如 <code>abc</code> 的游標在 b 前面，插入 X 時，先把後段 <code>bc</code> 向右移，再放入 X，得到 <code>aXbc</code>。刪除則反方向搬移。插入／刪除最壞 O(N)，對小型文字檔容易理解與管理，不需要複雜樹結構。</p><p>上下移動會掃描換行並保留目標欄位；按鍵解碼器逐 byte 處理 ANSI Escape 序列。畫面以逐行快取比較，只重畫改變的行。</p><h2 id="一個終端上的全螢幕介面" tabindex="-1">一個終端上的全螢幕介面 <a class="header-anchor" href="#一個終端上的全螢幕介面" aria-label="Permalink to &quot;一個終端上的全螢幕介面&quot;">​</a></h2><p>畫面經 UART 輸出 ANSI 游標定位、清行與色彩控制碼，需至少 80×24 終端。它是 TUI（文字使用者介面），沒有 framebuffer（像素畫面緩衝區）或圖形視窗系統。</p><p>編輯器持有 raw console，shell 等待子行程，不會同時讀走你的按鍵；背景行程輸出仍可能干擾畫面，尚無完整前景工作隔離。</p><h2 id="在-qemu-編輯" tabindex="-1">在 QEMU 編輯 <a class="header-anchor" href="#在-qemu-編輯" aria-label="Permalink to &quot;在 QEMU 編輯&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fan /home/user/note.txt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>按鍵</th><th>操作</th></tr></thead><tbody><tr><td>方向鍵／Home／End</td><td>移動游標</td></tr><tr><td>Enter／Tab</td><td>換行／插入空白</td></tr><tr><td>Backspace／Delete</td><td>刪除文字</td></tr><tr><td>PageUp／PageDown</td><td>捲動畫面</td></tr><tr><td>Ctrl+O</td><td>儲存</td></tr><tr><td>Ctrl+X</td><td>離開；修改未儲存時詢問 y／n／c</td></tr><tr><td>Ctrl+L</td><td>完整重畫</td></tr></tbody></table><p>輸入文字，Ctrl+O 儲存，再 Ctrl+X 返回 shell，使用 <code>cat /home/user/note.txt</code> 讀回。新檔直到儲存才建立，父目錄必須存在。</p><h2 id="限制與參考" tabindex="-1">限制與參考 <a class="header-anchor" href="#限制與參考" aria-label="Permalink to &quot;限制與參考&quot;">​</a></h2><p>UTF-8、超大檔案與不支援的控制字元會拒絕開啟，以免截斷覆寫。既有 Tab 以 <code>&gt;</code> 顯示並保留，新 Tab 插入空白。目前沒有 undo、搜尋、Vim 命令模式與原子儲存。</p><p>觀念參考：<code>notes/ch3 Process.md</code>、<code>notes/ch12 I_O Systems.md</code>；終端序列依 <a href="https://invisible-island.net/xterm/ctlseqs/ctlseqs.html" target="_blank" rel="noreferrer">XTerm 文件</a>。設計與既有互動驗收見 <a href="./../SPEC-09-fan.html">Spec 09</a>。</p>',22))])}const _=a(s,[["render",n]]);export{f as __pageData,_ as default};
